<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Auth,Database,Flash,View};final class DashboardController{public function index():void{Auth::requireLogin();$u=Auth::user();$a=null;$s=Database::pdo()->prepare('SELECT ua.*,r.name region_name,p.name park_name,a.name area_name,pos.name position_name FROM user_assignments ua LEFT JOIN regions r ON r.id=ua.region_id LEFT JOIN parks p ON p.id=ua.park_id LEFT JOIN areas a ON a.id=ua.area_id LEFT JOIN positions pos ON pos.id=ua.position_id WHERE ua.user_id=? AND ua.ended_at IS NULL ORDER BY ua.id DESC LIMIT 1');$s->execute([Auth::id()]);$a=$s->fetch()?:null;View::render('dashboard/index',['user'=>$u,'assignment'=>$a,'flash'=>Flash::pull()]);}}
